from itertools import combinations
from typing import Hashable, List, Sequence, Set, FrozenSet, Tuple

Vertex = Hashable

def is_clique(adj: Set[FrozenSet[Vertex]], s: Sequence[Vertex]) -> bool:
    """True iff every distinct pair of s is an edge."""
    return all(frozenset((u, v)) in adj for u, v in combinations(set(s), 2))

def clique_complex(vertices: Sequence[Vertex],
                   edges: Sequence[Tuple[Vertex, Vertex]]) -> Set[FrozenSet[Vertex]]:
    """Enumerate all faces of the clique complex Delta(G), level by level.

    Uses downward closure for pruning: a (k+1)-set can be a face only if every one
    of its k-subsets is already a face (apriori-style growth)."""
    adj: Set[FrozenSet[Vertex]] = {frozenset(e) for e in edges if e[0] != e[1]}
    faces: Set[FrozenSet[Vertex]] = {frozenset()}
    level: Set[FrozenSet[Vertex]] = {frozenset((v,)) for v in vertices}
    faces |= level
    k = 1
    while level:
        nxt: Set[FrozenSet[Vertex]] = set()
        for s in level:
            for v in vertices:
                if v in s:
                    continue
                cand = s | {v}
                if len(cand) != k + 1:
                    continue
                # downward-closure pruning + direct clique check
                if all((cand - {w}) in faces for w in cand) and is_clique(adj, cand):
                    nxt.add(cand)
        faces |= nxt
        level = nxt
        k += 1
    return faces

from itertools import combinations
from typing import Callable, Hashable, List, Sequence, Set, FrozenSet, Tuple

Vertex = Hashable

def vietoris_rips_filtration(
        vertices: Sequence[Vertex],
        d: Callable[[Vertex, Vertex], float],
        scales: Sequence[float]
) -> List[Tuple[float, Set[FrozenSet[Vertex]]]]:
    """Build the nested Vietoris-Rips complexes at an increasing list of scales.

    At each scale eps we threshold the dissimilarity symmetrically to form the
    proximity graph, then take its clique complex. By the monotonicity theorem the
    returned face sets are nested: faces[i] subset faces[i+1]."""
    result: List[Tuple[float, Set[FrozenSet[Vertex]]]] = []
    for eps in sorted(scales):
        edges = [(u, v) for u, v in combinations(vertices, 2)
                 if d(u, v) <= eps and d(v, u) <= eps]
        adj = {frozenset(e) for e in edges}
        faces: Set[FrozenSet[Vertex]] = {frozenset()}
        for k in range(1, len(vertices) + 1):
            for combo in combinations(vertices, k):
                if all(frozenset((u, v)) in adj for u, v in combinations(combo, 2)):
                    faces.add(frozenset(combo))
        result.append((eps, faces))
    return result
